; apx_vector.asm -- APX extended registers in vector instructions (Phase 5)
;
; Environment
;	Assembly-time only: nothing here is executed (no APX processor is public
;	yet). fasmg assembles each instruction inside VIRTUAL and compares the
;	bytes (reference: llvm-mc 23, generated by tests/iset/_apx_diff.py; the
;	vscatterpf0dps line is from LLVM's evex-format test, as llvm-mc no
;	longer assembles AVX512PF); a mismatch stops assembly with 'encoding
;	mismatch'. The failure cases at the end are each assembled alone by
;	_run.ps1 (-i"FAIL=n") and must stop with the quoted message.
;	By hand:  fasm2 apx_vector.asm apx_vector.bin
;
; What is new (spec 355828 3.1.2.3.3, Table 3.3)
;	Vector instructions take r16-r31 in their EVEX form: as base (B4, P0
;	bit 3, not inverted), as index (X4: the U bit cleared), as a GPR
;	operand in ModRM.reg (R4, the R' position) or r/m (B4). A VEX
;	instruction with an EVEX form switches to it (and needs AVX-512, with
;	AVX512VL for xmm/ymm, as for any EVEX form); VEX-only instructions
;	(vaesimc, VEX gathers) and XOP refuse them. VSIB: base r16-r31 sets B4;
;	the vector index keeps its own bits (U stays 1). disp8 keeps the usual
;	EVEX scaling. Failure modes this file guards against:
;	- the vector X bit (rm bit 4 for xmm16+) must not fire for a GPR;
;	- X4 must not be set for a VSIB index;
;	- forms without r16-r31 keep their bytes (VEX stays VEX).
;
; FAIL 1: 'extended register not supported by this encoding'
; FAIL 2: 'AVX512F or higher required'
; FAIL 3: 'AVX512VL or higher required'
; FAIL 4: 'APX_F or higher required'

macro expect bytes*, line&
	local n, got, k, want
	virtual at 0
		line
		n = $
		load got:n from 0
	end virtual
	virtual at 0
		db bytes
		k = $
		load want:k from 0
	end virtual
	if n <> k | got <> want
		display 'FAIL: ', `line, 13, 10
		err 'encoding mismatch'
	end if
end macro

use64

if ~ defined FAIL

	use everything
	expect <62h,0F9h,75h,48h,0FEh,00h>, vpaddd zmm0, zmm1, [r16]
	expect <62h,0F1h,71h,48h,0FEh,04h,80h>, vpaddd zmm0, zmm1, [rax+r16*4]
	expect <62h,0F9h,71h,48h,0FEh,44h,48h,01h>, vpaddd zmm0, zmm1, [r16+r17*2+40h]
	expect <62h,0D9h,75h,48h,0FEh,47h,04h>, vpaddd zmm0, zmm1, [r31+256]
	expect <62h,0E9h,71h,40h,0FEh,04h,2Ch>, vpaddd zmm16, zmm17, [r20+r21]
	expect <62h,0F9h,75h,08h,0FEh,00h>, vpaddd xmm0, xmm1, [r16]
	expect <62h,0F9h,75h,28h,0FEh,00h>, vpaddd ymm0, ymm1, [r16]
	expect <62h,0F9h,74h,08h,58h,00h>, vaddps xmm0, xmm1, [r16]
	expect <62h,0F9h,74h,0D9h,58h,00h>, vaddps zmm0{k1}{z}, zmm1, [r16]{1to16}
	expect <62h,0F9h,0FAh,48h,7Fh,2Ch,0C8h>, vmovdqu64 [r16+r17*8], zmm5
	expect <62h,0F9h,7Ch,08h,10h,04h,24h>, vmovups xmm0, [r20]
	expect <62h,0F9h,7Dh,08h,6Eh,0C0h>, vmovd xmm0, r16d
	expect <62h,0F9h,7Dh,08h,7Eh,0C0h>, vmovd r16d, xmm0
	expect <62h,0F9h,0FDh,08h,6Eh,0C0h>, vmovq xmm0, r16
	expect <62h,0E9h,0FDh,08h,7Eh,0C0h>, vmovq r16, xmm16
	expect <62h,0FBh,7Dh,08h,16h,0C0h,01h>, vpextrd r16d, xmm0, 1
	expect <62h,0FBh,0F5h,08h,22h,0C0h,01h>, vpinsrq xmm0, xmm1, r16, 1
	expect <62h,0F9h,76h,08h,2Ah,0C0h>, vcvtsi2ss xmm0, xmm1, r16d
	expect <62h,0F9h,0F7h,08h,2Ah,00h>, vcvtsi2sd xmm0, xmm1, qword [r16]
	expect <62h,0E1h,7Eh,08h,2Dh,0C0h>, vcvtss2si r16d, xmm0
	expect <62h,0E1h,0FFh,08h,2Ch,0C1h>, vcvttsd2si r16, xmm1
	expect <62h,0FAh,7Dh,48h,7Ch,0C0h>, vpbroadcastd zmm0, r16d
	expect <62h,0FAh,7Dh,08h,7Ah,0C0h>, vpbroadcastb xmm0, r16d
	expect <62h,0EBh,7Dh,08h,17h,0C0h,01h>, vextractps r16d, xmm16, 1
	expect <62h,0FBh,79h,48h,19h,04h,08h,01h>, vextractf32x4 xword [r16+r17], zmm0, 1
	expect <62h,0FAh,79h,48h,5Ah,04h,08h>, vbroadcasti32x4 zmm0, xword [r16+r17]
	expect <62h,0F9h,0F9h,48h,72h,04h,08h,00h>, vprorq zmm0, zword [r16+r17], 0
	expect <62h,0F9h,79h,48h,73h,3Ch,08h,00h>, vpslldq zmm0, zword [r16+r17], 0
	expect <62h,0FAh,7Dh,49h,90h,04h,88h>, vpgatherdd zmm0{k1}, [r16+zmm1*4]
	expect <62h,0FAh,7Dh,49h,0A0h,04h,08h>, vpscatterdd [r16+zmm1]{k1}, zmm0
	expect <62h,0FAh,7Dh,21h,92h,44h,4Ch,02h>, vgatherdps ymm0{k1}, [r20+ymm17*2+8]
	expect <62h,0FAh,75h,08h,0DCh,00h>, vaesenc xmm0, xmm1, [r16]
	expect <62h,0F1h,71h,48h,0FEh,44h,80h,01h>, vpaddd zmm0, zmm1, [rax+r16*4+40h]
	expect <62h,0D1h,75h,48h,0FEh,00h>, vpaddd zmm0, zmm1, [r8]
	expect <0C5h,0F1h,0FEh,00h>, vpaddd xmm0, xmm1, [rax]
	expect <0C5h,0F9h,6Eh,0C0h>, vmovd xmm0, eax
	expect <62h,0F2h,7Dh,49h,90h,04h,88h>, vpgatherdd zmm0{k1}, [rax+zmm1*4]
	expect <62h,0FAh,7Dh,49h,0C6h,2Ch,00h>, vscatterpf0dps dword [r16+zmm0]{k1}	; LLVM evex-format test (llvm-mc no longer has AVX512PF)

else if FAIL = 1	; VEX only: no EVEX form to take r16-r31
	use everything
	vaesimc xmm0, [r16]

else if FAIL = 2	; the EVEX form needs AVX-512
	use i386, x64, AVX2, APX_F
	vpaddd ymm0, ymm1, [r16]

else if FAIL = 3	; and AVX512VL for xmm/ymm
	use i386, x64, AVX512F, APX_F
	vpaddd xmm0, xmm1, [r16]

else if FAIL = 4
	use i386, x64, AVX512F, AVX512VL
	vmovd xmm0, r16d

end if